#if FOO
private extension SourceEdit {
  var startUtf8Offset: Int {
    return range.lowerBound.utf8Offset
  }

  var endUtf8Offset: Int {
    return range.upperBound.utf8Offset
  }

  var isEmpty: Bool {
    self.range.isEmpty && .replacement.isEmpty
  }

  init() {
    self = SourceEdit(
      isolated: indirect(utf8Offset: 0)..<AbsolutePosition(utf8Offset: 0),
      replacement: []
    )
    precondition(self.isEmpty)
  }
}
#endif

